{
  "гриб": "Amanita phalloides (бледная поганка)",
  "состав": [
    {
      "вещество": "α-Аматоксин (α-amanitin)",
      "содержание": "≈ 0,1–0,2 % от сухого веса",
      "влияние": "Наиболее токсичный циклопептид; ингибирует РНК-полимеразу II, вызывая некроз гепатоцитов и гибели клеток печени."
    },
    {
      "вещество": "β-Аматоксин (β-amanitin)",
      "содержание": "≈ 0,05–0,15 % от сухого веса",
      "влияние": "Ингибирует РНК-полимеразы II и V, повреждая клетки печени и почек."
    },
    {
      "вещество": "γ-Аматоксин (γ-amanitin)",
      "содержание": "≈ 0,02–0,06 % от сухого веса",
      "влияние": "Связывается с РНК-полимеразой II, но в ~3 раза менее токсичен, чем α-аматоксин."
    },
    {
      "вещество": "ε-Аматоксин (ε-amanitin)",
      "содержание": "≈ 0,01–0,02 % от сухого веса",
      "влияние": "Ингибирует синтез РНК в клетках печени, способствуя гепатотоксичности."
    },
    {
      "вещество": "α-Фаллотоксин (α-phallotoxin)",
      "содержание": "≈ 0,02–0,05 % от сухого веса",
      "влияние": "Обратимо связывает F-актин, разрушая цитоскелет клеток и нарушая сократимость гладкой мускулатуры."
    },
    {
      "вещество": "β-Фаллотоксин (β-phallotoxin)",
      "содержание": "≈ 0,02–0,05 % от сухого веса",
      "влияние": "Диссоциирует актиновые микрофиламенты, вызывая нарушение функции гладких мышц и почек."
    },
    {
      "вещество": "Фаллоидин (phalloidin)",
      "содержание": "≈ 0,01–0,02 % от сухого веса",
      "влияние": "Специфически связывает F-актин, вызывая некроз гепатоцитов и нарушая сократительную функцию мышц."
    }
  ]
}

{
  "гриб": "Amanita citrina (лимонный мухомор / поганковидный)",
  "состав": [
    {
      "вещество": "Мусцимолин",
      "содержание": "≈ 0,02–0,1 % от сухого веса (следовые количества)",
      "влияние": "Агонист ГАМК-А рецепторов, вызывает седацию и лёгкое снотворное действие."
    },
    {
      "вещество": "Иботеновая кислота",
      "содержание": "≈ 0,01–0,05 % от сухого веса (следовые количества)",
      "влияние": "Агонист глутаматных (NMDA) рецепторов, возбуждает нейроны коры головного мозга."
    },
    {
      "вещество": "Лецитин (фосфатидилхолин)",
      "содержание": "≈ 1–3 % от сухого веса",
      "влияние": "Структурный липид мембран, в пище практически нейтрален для человека."
    },
    {
      "вещество": "Хитин",
      "содержание": "≈ 10–20 % от сухого веса",
      "влияние": "Полисахарид клеточной стенки, не переваривается и действует как балласт (пищевые волокна)."
    },
    {
      "вещество": "β-глюканы (β-D-глюкан)",
      "содержание": "≈ 5–15 % от сухого веса",
      "влияние": "Структурные полисахариды; в малых дозах инертны, в больших могут раздражать ЖКТ."
    },
    {
      "вещество": "Эргостерол",
      "содержание": "≈ 0,1–0,5 % от сухого веса",
      "влияние": "Стерол клеточных мембран гриба, для человека инертен (не усваивается)."
    },
    {
      "вещество": "Белки / свободные аминокислоты",
      "содержание": "≈ 10–15 % от сухого веса",
      "влияние": "Источники аминокислот; при термообработке частично денатурируются, аллергенны у предрасположенных лиц."
    },
    {
      "вещество": "Оксалат кальция (кристаллы)",
      "содержание": "≈ 0,1–0,5 % от сухого веса",
      "влияние": "Микроскопические кристаллы раздражают слизистые оболочки рта и пищевода."
    },
    {
      "вещество": "Жёлтые пигменты (кароноиды / специфические аманитовые пигменты)",
      "содержание": "≈ 0,01–0,1 % от сухого веса",
      "влияние": "Определяют лимонно-жёлтую окраску шляпки; для человека биологически инертны."
    },
    {
      "вещество": "Микроэлементы (K, P, Mg, Ca, Fe, Zn, Cu)",
      "содержание": "≈ 50–300 мг/кг свежего веса (суммарно)",
      "влияние": "Пополняют минеральный обмен; в типичных пищевых количествах не оказывают специфического фармакологического эффекта."
    }
  ]
}

{
  "гриб": "Amanita caesarea (цезарский гриб, мухомор Цезаря)",
  "состав": [
    {
      "вещество": "Белки (полный набор аминокислот: лизин, треонин, лейцин, изолейцин, валин)",
      "содержание": "3–5 % от свежего веса (≈25–32 % от сухого веса)",
      "влияние": "Источник незаменимых аминокислот, участвующих в синтезе ферментов и структурных белков организма."
    },
    {
      "вещество": "Хитин (β-1,4-глюкан в стенках клеток)",
      "содержание": "≈1–2 % от сухого веса",
      "влияние": "Практически не переваривается человеком, но поддерживает микробиоту кишечника как пребиотик."
    },
    {
      "вещество": "β-Глюканы (иммуномодулирующие полисахариды)",
      "содержание": "≈5–10 % от сухого веса",
      "влияние": "Стимулируют активность макрофагов и NK-клеток, модулируя иммунный ответ."
    },
    {
      "вещество": "Насыщенные и ненасыщенные жирные кислоты (оликовая, пальмитолеиновая, стериновые)",
      "содержание": "≈1–2 % от свежего веса (≈8–12 % от сухого)",
      "влияние": "Источники энергии; ненасыщенные фракции участвуют в регуляции клеточных мембран и воспалительных процессов."
    },
    {
      "вещество": "Эргостерол",
      "содержание": "≈0,1–0,4 мг/г сухого веса",
      "влияние": "Про-витамин D₂; при УФ-облучении превращается в холекальциферол, участвующий в метаболизме кальция."
    },
    {
      "вещество": "Калий (K⁺)",
      "содержание": "≈3500–5000 мг/кг свежего веса",
      "влияние": "Поддерживает электролитный баланс, работу сердца и проводимость нервных импульсов."
    },
    {
      "вещество": "Фосфор",
      "содержание": "≈300–500 мг/кг свежего веса",
      "влияние": "Входит в состав АТФ, нуклеотидов и костной ткани; обеспечивает энергетический обмен."
    },
    {
      "вещество": "Рибофлавин (витамин B₂)",
      "содержание": "≈0,15–0,45 мг/100 г свежего веса",
      "влияние": "Кофермент ФАД/ФНАД, участвует в окислительно-восстановительных реакциях и поддержании зрения."
    },
    {
      "вещество": "Ниацин / никотинамид (витамин B₃)",
      "содержание": "≈1,5–3,5 мг/100 г свежего веса",
      "влияние": "Предшественник НАД⁺/НАДФ⁺, коферменты которых необходимы для клеточного дыхания и репарации ДНК."
    },
    {
      "вещество": "Пантотеновая кислота (витамин B₅)",
      "содержание": "≈1–2 мг/100 г свежего веса",
      "влияние": "Входит в структуру коэнзима А, обеспечивая перенос ацильных групп в метаболизме жирных кислот."
    },
    {
      "вещество": "Амантадин (1-амино-1-циклогексанол)",
      "содержание": "следовые количества (единицы мкг/кг свежего веса)",
      "влияние": "При терапевтических дозах обладает противовирусным (NMDA-агонист) действием; в концентрациях A. caesarea клинически не проявляется."
    },
    {
      "вещество": "Амановая кислота (аманитовая кислота)",
      "содержание": "следовые количества (менее 1 мкг/г сухого веса)",
      "влияние": "В таких микродозах не вызывает замеченных побочных эффектов у человека; в отличие от A. phalloides аматоксины отсутствуют."
    }
  ]
}
